package com.tripmateai.service.impl; import com.tripmateai.ai.AiProviderClient; import com.tripmateai.dto.request.packing.*; import com.tripmateai.dto.response.packing.*; import com.tripmateai.entity.*; import com.tripmateai.exception.*; import com.tripmateai.mapper.PackingMapper; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.PackingService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class PackingServiceImpl implements PackingService {private final TripRepository trips;private final PackingChecklistRepository checklists;private final PackingItemRepository items;private final AiProviderClient ai; private User user(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal u))throw new UnauthorizedException("Authentication required");return u.user();} private Trip trip(Long id){return trips.findByIdAndUser(id,user()).orElseThrow(()->trips.existsById(id)?new UnauthorizedException("You do not own this trip"):new ResourceNotFoundException("Trip not found"));} private PackingChecklist checklist(Long id){var t=trip(id);return checklists.findByTripAndUser(t,user()).orElseGet(()->{var c=new PackingChecklist();c.setTrip(t);c.setUser(user());c.setName(t.getTripName()+" Packing");return checklists.save(c);});} private PackingItem item(Long t,Long id){return items.findByIdAndChecklist(id,checklist(t)).orElseThrow(()->new ResourceNotFoundException("Packing item not found"));} public PackingChecklistResponse get(Long id){var c=checklist(id);return PackingMapper.checklist(c,items.findByChecklist(c));} public PackingItemResponse add(Long id,CreatePackingItemRequest r){var c=checklist(id);if(items.findByChecklistAndNameIgnoreCase(c,r.name()).isPresent())throw new BadRequestException("Packing item already exists");var i=new PackingItem();i.setChecklist(c);i.setName(r.name());i.setQuantity(r.quantity());i.setCategory(r.category().toUpperCase());return PackingMapper.item(items.save(i));} public PackingItemResponse update(Long t,Long id,UpdatePackingItemRequest r){var i=item(t,id);i.setName(r.name());i.setQuantity(r.quantity());i.setCategory(r.category().toUpperCase());i.setPacked(r.packed());return PackingMapper.item(items.save(i));} public PackingItemResponse toggle(Long t,Long id){var i=item(t,id);i.setPacked(!i.isPacked());return PackingMapper.item(items.save(i));} public void delete(Long t,Long id){items.delete(item(t,id));} public PackingChecklistResponse generate(Long id,GeneratePackingRequest r){var c=checklist(id);for(var suggestion:ai.generatePacking(trip(id),r.preferences())){if(suggestion==null||suggestion.name()==null||suggestion.name().isBlank()||suggestion.quantity()==null||suggestion.quantity()<1||suggestion.category()==null||suggestion.category().isBlank())throw new BadRequestException("AI returned an invalid packing item");if(items.findByChecklistAndNameIgnoreCase(c,suggestion.name()).isEmpty()){var i=new PackingItem();i.setChecklist(c);i.setName(suggestion.name());i.setQuantity(suggestion.quantity());i.setCategory(suggestion.category().toUpperCase());items.save(i);}}return PackingMapper.checklist(c,items.findByChecklist(c));}}
